"""Leaderboards are derived from immutable run JSON, never hand-entered numbers."""

import json
from collections import defaultdict
from pathlib import Path


def reports(directory: Path) -> list[dict]:
    return [
        json.loads(path.read_text(encoding="utf-8"))
        for path in sorted((directory / "runs").glob("*.json"))
    ]


def write_leaderboard(directory: Path) -> Path:
    runs = reports(directory)
    lines = [
        "# Measured leaderboard",
        "",
        "Generated by `scripts/run_bench.py` from raw run JSON. Compare only within the same workload/hardware group. Hash-vector rows measure mechanics, not semantic quality. Relevance uses synthetic judgments.",
        "",
    ]
    groups = defaultdict(list)
    for run in runs:
        key = (
            run["dataset_sha256"],
            run["queries_sha256"],
            run["hardware_id"],
            run["config"]["metric"],
            run["config"]["k"],
            run["config"]["threads"],
            run["embedding"]["space"],
            run["method"].get("recall_semantics", "strict-id"),
        )
        groups[key].append(run)
    emitted_anchors = set()
    for key, group in groups.items():
        for run in group:
            anchor = run["config"]["name"].replace("-", "_")
            if anchor not in emitted_anchors:
                lines += [f'<a id="{anchor}"></a>', ""]
                emitted_anchors.add(anchor)
        sample = group[0]
        machine = sample["hardware"]
        lines += [
            f"## Workload {key[0][:10]} / queries {key[1][:10]} / hardware {key[2]}",
            "",
            f"{sample['record_count']:,} records; {sample['query_count']} queries; {key[3]}, k={key[4]}, threads={key[5]}. {sample['embedding']['space']}",
            "",
            f"Recall: {key[7]}. Hardware: {machine['cpu']}; {machine['physical_cores']} physical cores; {machine['ram_bytes'] / 2**30:.1f} GiB RAM; {machine['os']}; Python {machine['python']}.",
            "",
            "| Configuration / raw run | Recall@k | nDCG@k | p50 ms | p95 ms | p99 ms | QPS ± SD | Build s | Peak RSS MiB | Disk MiB |",
            "|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|",
        ]
        for run in group:
            s = run["summary"]
            recall = f"{s['recall_at_k']:.4f}" if s["recall_at_k"] is not None else "n/a"
            ndcg = f"{s['ndcg_at_k']:.4f}" if s["ndcg_at_k"] is not None else "n/a"
            lines.append(
                f"| [{run['config']['name']}](runs/{run['run_id']}.json) | {recall} | {ndcg} | {s['p50_ms']:.3f} | {s['p95_ms']:.3f} | {s['p99_ms']:.3f} | {s['qps']:.1f} ± {s['qps_std']:.1f} | {s['index_build_seconds']:.4f} | {run['memory']['process_peak_rss_bytes'] / 2**20:.1f} | {s['persisted_bytes'] / 2**20:.2f} |"
            )
        lines.append("")
    if not runs:
        lines += [
            "No measurements yet. Run `uv run python scripts/run_bench.py configs/bench/exact_fixture.yaml`.",
            "",
        ]
    lines += [
        "Insertion and index-build times are separate in raw results. RSS is sampled process memory including interpreter/libraries; it is not index-only memory. Disk is the persisted snapshot. Index build for an exact scan has no ANN training. Tied boundary neighbors can differ at floating-point precision; inspect ground truth and hit IDs before interpreting a small recall difference.",
        "",
    ]
    path = directory / "leaderboard.md"
    features = defaultdict(list)
    for raw in sorted((directory / "features").glob("*.json")):
        feature = json.loads(raw.read_text(encoding="utf-8"))
        features[feature["profile"]["feature"]].append((feature, raw))
    if features:
        lines.extend(
            [
                "",
                "## Measured lesson features",
                "",
                "Each profile ran the scratch and native scripts. Raw observations include their outputs, hardware and timing boundaries. Some features also link a repeated retrieval benchmark. Disk reads, model prefixes and reranking are measured separately from retrieval QPS.",
                "",
            ]
        )
        for name, records in sorted(features.items()):
            feature, raw = max(records, key=lambda pair: pair[0]["created_at"])
            rid = feature.get("retrieval_run")
            retrieval = f" · [retrieval run](runs/{rid}.json)" if rid else ""
            lines.extend(
                [
                    f'<a id="{name}"></a>',
                    "",
                    f"- **{name}** · [feature observation](features/{raw.name}){retrieval}",
                    "",
                ]
            )
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text("\n".join(lines), encoding="utf-8")
    return path
